import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Probabilità assiomatica","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/lc/lcg.md","filePath":"lezioni/l_calcolo-delle-probabilita/lc/lcg.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/lc/lcg.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="probabilita-assiomatica" tabindex="-1">Probabilità assiomatica <a class="header-anchor" href="#probabilita-assiomatica" aria-label="Permalink to “Probabilità assiomatica”">​</a></h1><blockquote><p>Per il biennio unificato e per alcuni tipi di scuola è sufficiente la parte di probabilità sin qui sviluppata. Invece per il triennio, nella maggior parte delle scuole, si sviluppa la teoria assiomatica. Tu segui il programma fatto dal tuo Professore.</p></blockquote><p>Abbiamo così tre tipi diversi di probabilità che è possibile applicare in contesti diversi: occorre ora unificare il tutto per avere una costruzione organica per la probabilità.</p><p>Per fare ciò considereremo degli oggetti generici (eventi), ne considereremo lo spazio in cui sono definiti (spazio degli eventi) e ne daremo i postulati che regoleranno la teoria delle probabilità assiomatica, in modo tale che restringendo tale teoria alla teoria classica, alla teoria frequentista od alla teoria soggettiva possiamo ritrovare le proprietà già viste.</p><ul><li><a href="./lcga.html">Campo di eventi</a></li><li><a href="./lcgb.html">Assiomi della probabilità</a></li><li><a href="./lcgc.html">Conseguenze</a></li></ul>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};